mapper.sql:
WHERE m.is_deleted = 0

    AND m.kind = #{kind}


    AND m.original_name LIKE CONCAT('%', #{name}, '%')


    AND m.source_type = #{sourceType}




            AND (m.category IS NULL OR m.category = '')


            AND m.category = #{category}




    AND EXISTS (
        SELECT 1 FROM material_clip_tag t
        WHERE t.is_deleted = 0
          AND t.clip_id = m.id
          AND t.tag_id IN
          #{tid}
    )

mapper.select:
SELECT
FROM material_clip m
ORDER BY m.id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE material_clip
SET tags_cache = #{tagsCache}, update_at = CURRENT_TIMESTAMP
WHERE is_deleted = 0 AND id = #{id}

UPDATE material_clip
SET is_deleted = 1, update_at = CURRENT_TIMESTAMP
WHERE is_deleted = 0 AND id = #{id}
